package dev.gbppimentel.zzz;
import android.app.usage.*;import android.content.Context;import android.os.*;import android.util.SparseIntArray;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.TimeUnit;
/** Read-only game-surface FPS and on-device ZZZ playtime. Never changes game or launcher settings. */
final class DeviceStatsReader implements Runnable {
 volatile JSONObject latest=new JSONObject();Context system;UsageStatsManager usage;String surface="";long listedAt,playReadAt;JSONObject play=new JSONObject();
 static String command(String... arguments)throws Exception{java.lang.Process p=new ProcessBuilder(arguments).redirectErrorStream(true).start();try{if(!p.waitFor(1800,TimeUnit.MILLISECONDS))throw new IOException("Statistics timed out");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=p.getInputStream()){byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>131072)throw new IOException("Statistics too large");bytes.write(b,0,n);}}if(p.exitValue()!=0)throw new IOException("Statistics unavailable");return bytes.toString("UTF-8");}finally{p.destroy();}}
 void initialize()throws Exception{if(Looper.getMainLooper()==null)Looper.prepareMainLooper();Object thread=Class.forName("android.app.ActivityThread").getMethod("systemMain").invoke(null);system=(Context)thread.getClass().getMethod("getSystemContext").invoke(thread);usage=system.getSystemService(UsageStatsManager.class);}
 boolean interactive(){try{return system==null||system.getSystemService(PowerManager.class).isInteractive();}catch(Exception ignored){return true;}}
 JSONObject playtime(boolean visible)throws Exception{long now=System.currentTimeMillis();try{if(usage!=null){List<UsageStats> game=new ArrayList<>();for(UsageStats s:usage.queryUsageStats(UsageStatsManager.INTERVAL_YEARLY,0,now))if("com.HoYoverse.Nap".equals(s.getPackageName()))game.add(s);if(!game.isEmpty()){long total=0;UsageStats newest=null;Set<String> buckets=new HashSet<>();for(UsageStats s:game){String key=s.getFirstTimeStamp()+":"+s.getLastTimeStamp();if(buckets.add(key))total+=Math.max(0,s.getTotalTimeInForeground());if(newest==null||s.getLastTimeStamp()>newest.getLastTimeStamp())newest=s;}if(visible&&newest!=null){try{SparseIntArray activities=(SparseIntArray)newest.getClass().getField("mActivities").get(newest);boolean active=false;for(int i=0;i<activities.size();i++)active|=activities.valueAt(i)==UsageEvents.Event.ACTIVITY_RESUMED;if(active)total+=Math.max(0,now-newest.getLastTimeUsed());}catch(Exception ignored){}}return new JSONObject().put("available",true).put("totalMs",total).put("at",now).put("source","Android Usage History");}}}catch(Exception ignored){}
  // Same retained historical source as Hades, when Android usage history is unavailable.
  try(SQLiteDatabase db=SQLiteDatabase.openDatabase("/data/user/0/rip.moth.cocoonshell/databases/cocoon_db",null,SQLiteDatabase.OPEN_READONLY|SQLiteDatabase.NO_LOCALIZED_COLLATORS);Cursor c=db.rawQuery("SELECT id,playTimeMinutes FROM games WHERE uri=? LIMIT 2",new String[]{"package:com.HoYoverse.Nap"})){if(c.moveToFirst()){long id=c.getLong(0),minutes=Math.max(0,c.getLong(1));if(c.moveToNext())return new JSONObject().put("available",false);long total=minutes*60000;try(Cursor pending=db.rawQuery("SELECT startTimeMs,pauseStartedAtMs,excludedDurationMs FROM pending_game_sessions WHERE gameId=? AND finalizedAtMs IS NULL AND state IN ('ACTIVE','PAUSED','GRACE') ORDER BY createdAtMs DESC LIMIT 1",new String[]{Long.toString(id)})){if(pending.moveToFirst()){long end=pending.isNull(1)?now:Math.min(now,pending.getLong(1));total+=Math.max(0,end-pending.getLong(0)-pending.getLong(2));}}return new JSONObject().put("available",true).put("totalMs",total).put("at",now).put("source","Cocoon");}}return new JSONObject().put("available",false);}
 public void run(){try{try{initialize();}catch(Exception ignored){}GameCapture.Foreground foreground=new GameCapture.Foreground();while(GameObserver.watching()){long started=System.currentTimeMillis();boolean visible=foreground.gameVisible()&&interactive();JSONObject out=new JSONObject().put("at",started);try{if(started-playReadAt>=15000||playReadAt==0){playReadAt=started;play=playtime(visible);}}catch(Exception ignored){}out.put("playtime",play);JSONObject fps=new JSONObject().put("available",false).put("source","Game Surface");
  if(visible)try{if(surface.isEmpty()||started-listedAt>=5000){List<String> layers=FrameRate.layers(command("/system/bin/dumpsys","SurfaceFlinger","--list"));surface=layers.isEmpty()?"":layers.get(layers.size()-1);listedAt=started;}if(!surface.isEmpty()){FrameRate.Sample sample=FrameRate.parse(command("/system/bin/dumpsys","SurfaceFlinger","--latency",surface),System.nanoTime());if(sample.fps!=null&&foreground.gameVisible()&&interactive())fps.put("available",true).put("value",sample.fps).put("frames",sample.frames);else{surface="";listedAt=started;}}}catch(Exception ignored){surface="";}
  out.put("fps",fps);latest=out;long used=System.currentTimeMillis()-started;Thread.sleep(Math.max(100,1000-used));}}
 catch(Exception ignored){}}
}
